import{_ as t,o as r,c as s,a2 as o}from"./chunks/framework.CqdVOxXJ.js";const a="/rakkii-cars-guide/screenshots/v2/a11-release-can-leave.png",n="/rakkii-cars-guide/screenshots/v2/a15-release-form.png",m=JSON.parse('{"title":"7. Release the car","description":"","frontmatter":{},"headers":[],"relativePath":"desk/job/07-release.md","filePath":"desk/job/07-release.md","lastUpdated":1794621279000}'),i={name:"desk/job/07-release.md"};function l(d,e,h,c,g,p){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="_7-release-the-car" tabindex="-1">7. Release the car <a class="header-anchor" href="#_7-release-the-car" aria-label="Permalink to &quot;7. Release the car&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin · <strong>Where:</strong> the job&#39;s <strong>Release</strong> tab · <strong>Status after:</strong> Released</p><h2 id="check-can-the-car-leave" tabindex="-1">Check &quot;Can the car leave?&quot; <a class="header-anchor" href="#check-can-the-car-leave" aria-label="Permalink to &quot;Check &quot;Can the car leave?&quot;&quot;">​</a></h2><p>Open the <strong>Release</strong> tab. The <strong>Can the car leave?</strong> list shows each check with ✓, ✗ or !, and a button that takes you to the fix:</p><table tabindex="0"><thead><tr><th>Check</th><th>If it&#39;s not done, press</th></tr></thead><tbody><tr><td><strong>Ready for pickup</strong></td><td><strong>Mark ready</strong></td></tr><tr><td><strong>Customer invoice posted</strong></td><td><strong>Bill on Pay</strong></td></tr><tr><td><strong>QC photos</strong> (4/4)</td><td><strong>Add photos</strong></td></tr><tr><td><strong>Customer balance</strong></td><td><strong>Record payment</strong></td></tr><tr><td><strong>Deposit before release</strong></td><td><strong>Record payment</strong></td></tr><tr><td><strong>Surrendered parts</strong> (insurance jobs)</td><td><strong>Log parts</strong></td></tr></tbody></table><p>For example, in the picture below the car isn&#39;t ready and the photos are missing, but the invoice is posted and the customer has paid.</p><p><img src="'+a+'" alt="Can the car leave? list on a job still at Quality check"></p><h2 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;Release&quot;">​</a></h2><p>The release form opens once the job is <strong>Ready for pickup</strong>.</p><ol><li>Print what you need from <strong>Print ▾</strong>: <strong>Gate pass</strong> for the guard, <strong>Acceptance</strong> for the customer to sign, and the <strong>Customer invoice</strong>.</li><li>Tick the three checks: <ul><li><strong>Keys logged</strong></li><li><strong>Documents in / out</strong></li><li><strong>Customer signed acceptance &amp; release</strong></li></ul></li><li>Optional: add a <strong>Release / signature photo</strong>.</li><li><strong>PMS reminder</strong>: for maintenance work, choose <strong>In 3 months</strong>, <strong>In 6 months</strong> or <strong>In 12 months</strong>. The customer gets one reminder email when it&#39;s due. Otherwise leave it at <strong>None</strong>.</li><li>Press <strong>Release car</strong>. The app asks &quot;Release GDE 101? The car leaves the shop.&quot; Press <strong>Release car</strong> again.</li></ol><p><img src="'+n+'" alt="Release form with the checks ticked and a 6-month PMS reminder"></p><p>The job becomes <strong>Released</strong> (&quot;Car released.&quot;). The <strong>Released</strong> card shows who released it and when, the three checks, and the PMS reminder date.</p><div class="tip custom-block"><p class="custom-block-title">Rakkii&#39;s hand-over routine</p><p>Before ticking <strong>Customer signed acceptance &amp; release</strong>, make sure the customer signed the acceptance form, the old parts were returned, and the car was washed and vacuumed.</p></div><h2 id="if-something-stops-you" tabindex="-1">If something stops you <a class="header-anchor" href="#if-something-stops-you" aria-label="Permalink to &quot;If something stops you&quot;">​</a></h2><p>Only the owner can release past a block, and always with a written reason:</p><ul><li><strong>Owner override</strong> with an <strong>Override reason</strong>: the customer still owes, or a check isn&#39;t ticked.</li><li><strong>Reason to release before invoices are posted</strong>: when the shop holds release until invoices are posted.</li></ul><p><strong>Next:</strong> <a href="/rakkii-cars-guide/desk/job/08-mark-done">8. Mark the job done</a></p>',17)])])}const k=t(i,[["render",l]]);export{m as __pageData,k as default};
